152	impl File {
153	  pub fn resolve_media_type_and_charset(&self) -> (MediaType, Option<&str>) {
154	    deno_media_type::resolve_media_type_and_charset_from_content_type(
155	      &self.url,
156	      self
157	        .maybe_headers
158	        .as_ref()
159	        .and_then(|h| h.get("content-type"))
160	        .map(|v| v.as_str()),
161	    )
162	  }
163	}
